import { splitProps, type JSX, type ParentProps } from 'solid-js';
import { kbdStyleKeys } from '../lib/core';
import styles from './kbd.module.scss';
export interface KbdProps extends JSX.HTMLAttributes<HTMLElement> {}
export function Kbd(props: ParentProps<KbdProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<kbd {...rest} class={`${styles[kbdStyleKeys.base]} ${local.class ?? ''}`}>
			{local.children}
		</kbd>
	);
}
export interface KbdGroupProps extends JSX.HTMLAttributes<HTMLElement> {}
export function KbdGroup(props: ParentProps<KbdGroupProps>) {
	const [local, rest] = splitProps(props, ['class', 'children']);
	return (
		<kbd {...rest} class={`${styles[kbdStyleKeys.group]} ${local.class ?? ''}`}>
			{local.children}
		</kbd>
	);
}
export default Kbd;

@use '../../../styles/variables/colors' as *;

.kbd {
	pointer-events: none;
	display: inline-flex;
	height: 1.25rem;
	width: fit-content;
	min-width: 1.25rem;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	border-radius: var(--tile-kbd-radius, $radius-sm);
	background-color: var(--tile-kbd-background, $muted);
	box-shadow: var(--tile-kbd-shadow, none);
	padding: 0 $spacing-1;
	font-family: $font-sans;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: var(--tile-kbd-color, $muted-foreground);
	user-select: none;

	svg {
		width: 0.75rem;
		height: 0.75rem;
	}
}

.kbdGroup {
	display: inline-flex;
	align-items: center;
	gap: $spacing-1;
}
